create extension if not exists pgcrypto;
create type public.task_status as enum ('inbox','next','planned','in_progress','done','deferred','dropped','delegated');
create table public.projects (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null,purpose text not null default '',definition_of_done text not null default '',status text not null default 'active',next_review date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.tasks (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,parent_task_id uuid references public.tasks(id),project_id uuid references public.projects(id),title text not null,description_markdown text not null default '',status public.task_status not null default 'inbox',priority smallint not null default 3 check(priority between 1 and 4),energy text not null default 'medium' check(energy in ('low','medium','high')),estimated_minutes integer,estimate_low_minutes integer,estimate_high_minutes integer,estimate_confidence text not null default 'low',due_date date,planned_for_date date,next_action_text text not null default '',defer_count integer not null default 0,last_defer_reason text,rollover_state text not null default 'clear',sort_order bigint not null default 0,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.task_events (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references public.tasks(id),event_type text not null,occurred_at timestamptz not null default now(),minutes integer,metadata jsonb not null default '{}');
create table public.sync_operations (operation_id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,device_id uuid not null,entity_type text not null,entity_id uuid not null,base_version integer not null,kind text not null,fields jsonb not null,client_created_at timestamptz not null,processed_at timestamptz not null default now(),result jsonb not null default '{}');
create table public.sync_conflicts (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,entity_type text not null,entity_id uuid not null,field text not null,local_value jsonb,remote_value jsonb,resolved_at timestamptz,created_at timestamptz not null default now());
alter table public.projects enable row level security;alter table public.tasks enable row level security;alter table public.task_events enable row level security;alter table public.sync_operations enable row level security;alter table public.sync_conflicts enable row level security;
create policy owner_all_projects on public.projects for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_tasks on public.tasks for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_events on public.task_events for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_operations on public.sync_operations for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy owner_all_conflicts on public.sync_conflicts for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
insert into storage.buckets(id,name,public) values('attachments','attachments',false) on conflict do nothing;
create policy attachment_owner on storage.objects for all using(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text);
